{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not specify encryption for the root block device, potentially leaving data stored on the instance's Elastic Block Store (EBS) unencrypted."
    },
    {
      "check_id": "CKV_AWS_389",
      "title": "Ensure AWS Auto Scaling group launch configuration doesn't have public IP address assignment enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration has 'associate_public_ip_address' set to true, which can expose instances to the public internet."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "Launch configuration does not require IMDS access to require a token",
      "resource": "aws_launch_configuration.lc",
      "severity": "HIGH",
      "explanation": "The launch configuration does not require a token for IMDS access, allowing unrestricted access to instance metadata."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"lc\" {\n  name          = \"test_ecs\"\n  image_id      = data.aws_ami.amazon_linux.id\n  instance_type = \"t2.micro\"\n  lifecycle {\n    create_before_destroy = true\n  }\n  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name\n  key_name                    = var.key_name\n  security_groups             = [aws_security_group.ec2-sg.id]\n  associate_public_ip_address = false\n  user_data                   = <<EOF\nsudo apt-get update\nsudo echo \"ECS_CLUSTER=${var.cluster_name}\" >> /etc/ecs/ecs.config\nEOF\n  metadata_options {\n    http_tokens = \"required\"\n  }\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Added 'root_block_device' with 'encrypted = true' to ensure EBS encryption, set 'associate_public_ip_address' to false to prevent public IP assignment, and added 'metadata_options' with 'http_tokens = required' to enforce IMDSv2."
}
